pub const FRAME_T: u32 = 70224;

/// 一帧画面：160×144，行优先。
pub type Frame = [u8; FRAME_PIXELS];

/// 中断位（IF/IE 的 bit 序号与掩码）。`CpuBus::ack` 接收的是 bit 序号 0..=4。
pub mod irq {
    pub const VBLANK: u8 = 1 << 0;
    pub const STAT: u8 = 1 << 1;
    pub const TIMER: u8 = 1 << 2;
    pub const SERIAL: u8 = 1 << 3;
    pub const JOYPAD: u8 = 1 << 4;
}

/// `Machine::set_buttons` 的位定义：1 = 按下。
pub mod buttons {
    pub const A: u8 = 1 << 0;
    pub const B: u8 = 1 << 1;
    pub const SELECT: u8 = 1 << 2;
    pub const START: u8 = 1 << 3;
    pub const RIGHT: u8 = 1 << 4;
    pub const LEFT: u8 = 1 << 5;
    pub const UP: u8 = 1 << 6;
    pub const DOWN: u8 = 1 << 7;
}

/// 外设统一形态（timer/serial/joypad/ppu 都遵守；DMA 另有接口，见 `dma.rs`）。
///
/// Bus 每个 M-cycle 依次调用 timer → serial → joypad → ppu 的 `tick_mcycle`，再推进 DMA，
/// 并把返回的中断位或进 IF。`read_reg` 必须无副作用（`Machine::peek` 也走它）。
pub trait Peripheral: Snapshot {
    /// 推进 1 个 M-cycle（4 T），返回本周期新请求的中断位（IF 位掩码，见 `irq`）。
    fn tick_mcycle(&mut self) -> u8;
    /// 读 I/O 寄存器，`addr` 为绝对地址（如 0xFF04）。
    fn read_reg(&self, addr: u16) -> u8;
    /// 写 I/O 寄存器，`addr` 为绝对地址。
    fn write_reg(&mut self, addr: u16, v: u8);
}
//! MBC1（platform 通道；PLAN §3.6）。T02 空壳。
//! MBC2（platform 通道；PLAN §3.6）。T02 空壳。
//! MBC3（platform 通道；PLAN §3.6）。T02 空壳。
//! MBC5（platform 通道；PLAN §3.6）。T02 空壳。
//! 卡带（platform 通道，T50/T50b；PLAN §3.6）。
//!
//! 冻结部分（D001）：`Cart` trait、`from_rom`、`CartError`。
//! T02 临时实现：头部类型为 ROM only、MBC1、MBC3 且 ROM 不超过 32 KiB 时，一律按 ROM only 处理
//! （忽略 MBC 寄存器写入，无卡带 RAM），足够运行 32 KiB 的 Blargg individual ROM；T50 替换。

mod mbc1;
mod mbc2;
mod mbc3;
mod mbc5;

use std::fmt;

use crate::state::{Snapshot, StateError, StateReader, StateWriter};

/// 卡带：ROM 区 0000–7FFF 与外部 RAM 区 A000–BFFF。读方法必须无副作用（`peek` 也走它们）。
pub trait Cart: Snapshot + Send {
    /// 读 ROM 区，`addr` 为 0x0000..=0x7FFF。
    fn read_rom(&self, addr: u16) -> u8;
    /// 写 ROM 区（MBC 寄存器），`addr` 为 0x0000..=0x7FFF。
    fn write_rom(&mut self, addr: u16, v: u8);
    /// 读外部 RAM 区，`addr` 为 0xA000..=0xBFFF；RAM 未使能或不存在时读 0xFF。
    fn read_ram(&self, addr: u16) -> u8;
    /// 写外部 RAM 区，`addr` 为 0xA000..=0xBFFF；RAM 未使能或不存在时忽略。
    fn write_ram(&mut self, addr: u16, v: u8);
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum CartError {
    /// ROM 小于 0x150 字节（放不下头部）或不是 16 KiB 的整数倍。
    BadSize(usize),
    /// 不支持的卡带类型（头部 0x147）。
    UnsupportedType(u8),
}

impl fmt::Display for CartError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            CartError::BadSize(n) => write!(f, "bad ROM size: {n} bytes"),
            CartError::UnsupportedType(t) => write!(f, "unsupported cartridge type 0x{t:02X}"),
        }
    }
}

impl std::error::Error for CartError {}

/// 解析头部并选择 MBC。未知类型返回 `CartError`，不 panic。
pub fn from_rom(rom: Vec<u8>) -> Result<Box<dyn Cart>, CartError> {
    if rom.len() < 0x150 {
        return Err(CartError::BadSize(rom.len()));
    }
    let kind = rom[0x147];
    match kind {
        0x00..=0x03 | 0x0F..=0x13 if rom.len() <= 0x8000 => Ok(Box::new(RomOnly::new(rom))),
        _ => Err(CartError::UnsupportedType(kind)),
    }
}

/// ROM only（类型 0x00）：32 KiB 直接映射，无 RAM。
pub struct RomOnly {
    rom: Vec<u8>,
}

impl RomOnly {
    pub fn new(mut rom: Vec<u8>) -> Self {
        rom.resize(0x8000, 0xFF);
        Self { rom }
    }
}

impl Cart for RomOnly {
    fn read_rom(&self, addr: u16) -> u8 {
        self.rom[(addr & 0x7FFF) as usize]
    }
    fn write_rom(&mut self, _addr: u16, _v: u8) {}
    fn read_ram(&self, _addr: u16) -> u8 {
        0xFF
    }
    fn write_ram(&mut self, _addr: u16, _v: u8) {}
}

impl Snapshot for RomOnly {
    fn save(&self, w: &mut StateWriter) {
        w.tag(b"CART");
    }
    fn load(&mut self, r: &mut StateReader) -> Result<(), StateError> {
        r.tag(b"CART")
    }
}
//! 整机（T02 由 integrator 写骨架，之后归 sys 通道）。
//!
//! 冻结部分（D001）：`Machine` 的全部公开方法与 `Regs`（PLAN §3.2）。cli、ffi、Python 只经由它们访问核心。

use crate::bus::Bus;
use crate::cart::{self, CartError};
use crate::cpu::Cpu;
use crate::state::StateError;
use crate::{Frame, FRAME_T};

/// 寄存器快照（`Machine::regs`）。
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct Regs {
    pub a: u8,
    pub f: u8,
    pub b: u8,
    pub c: u8,
    pub d: u8,
    pub e: u8,
    pub h: u8,
    pub l: u8,
    pub sp: u16,
    pub pc: u16,
    pub ime: bool,
    pub halted: bool,
}

pub struct Machine {
    cpu: Cpu,
    bus: Bus,
    /// `run_frame` 的 T-cycle 余量：每帧加 70224，执行到不大于 0；超出部分累计到下一帧。
    frame_budget: i64,
}

impl Machine {
    /// 解析头部、选择 MBC、设置 DMG 开机状态。
    pub fn new(rom: Vec<u8>) -> Result<Self, CartError> {
        if rom.len() < 0x150 {
            return Err(CartError::BadSize(rom.len()));
        }
        let header_checksum = rom[0x14D];
        let cart = cart::from_rom(rom)?;
        let mut cpu = Cpu::new();
        // Power_Up_Sequence：头部校验和为 0 时 H、C 清零，否则置位（Z=1、N=0 不变）。
        cpu.f = if header_checksum == 0 { 0x80 } else { 0xB0 };
        Ok(Self { cpu, bus: Bus::new(cart), frame_budget: 0 })
    }

    /// 执行 1 条指令或 1 次中断分派，返回消耗的 T 数；HALT/STOP/锁死时也至少返回 4，绝不返回 0。
    pub fn step(&mut self) -> u32 {
        let start = self.bus.mcycles();
        self.cpu.step(&mut self.bus);
        ((self.bus.mcycles() - start) * 4) as u32
    }

    /// 精确推进 70224 T（余量累计到下一帧），与 LCD 开关无关。
    pub fn run_frame(&mut self) {
        self.frame_budget += FRAME_T as i64;
        while self.frame_budget > 0 {
            self.frame_budget -= self.step() as i64;
        }
    }

    /// bit0..7 = A B Select Start Right Left Up Down，1 = 按下（见 `crate::buttons`）。
    pub fn set_buttons(&mut self, mask: u8) {
        self.bus.set_buttons(mask);
    }

    /// 最近一个完整帧（前缓冲），值为 0xFF/0xAA/0x55/0x00。
    pub fn frame(&self) -> &Frame {
        self.bus.frame()
    }

    /// 无副作用读（不推进时钟，不触发任何寄存器副作用）。
    pub fn peek(&self, addr: u16) -> u8 {
        self.bus.peek(addr)
    }

    /// 取走自上次调用以来串口发出的字节（内部时钟传输开始时追加）。
    pub fn take_serial(&mut self) -> Vec<u8> {
        self.bus.take_serial()
    }

    pub fn regs(&self) -> Regs {
        let c = &self.cpu;
        Regs {
            a: c.a,
            f: c.f,
            b: c.b,
            c: c.c,
            d: c.d,
            e: c.e,
            h: c.h,
            l: c.l,
            sp: c.sp,
            pc: c.pc,
            ime: c.ime,
            halted: c.halted,
        }
    }

    /// 自上次查询以来是否执行过 0x40（LD B,B），读后清零。
    pub fn ld_b_b_hit(&mut self) -> bool {
        std::mem::take(&mut self.cpu.ld_b_b)
    }

    /// 开机以来累计的 T-cycle 数。
    pub fn cycles(&self) -> u64 {
        self.bus.mcycles() * 4
    }

    /// 存档：magic `GBEMUST`、版本 u16、ROM 指纹，然后依次是各模块的 `Snapshot`（PLAN §3.8）。
    pub fn save_state(&self) -> Vec<u8> {
        todo!("sys: Machine::save_state (T13)")
    }

    /// 读档；ROM 指纹不匹配时返回 `StateError::RomMismatch`，失败时机器状态保持不变。
    pub fn load_state(&mut self, _data: &[u8]) -> Result<(), StateError> {
        todo!("sys: Machine::load_state (T13)")
    }
}
//! 存档的小端字节读写与 `Snapshot` trait（T02 冻结并完整实现）。
//!
//! 每个模块的所有者随模块实现 `Snapshot`：`save` 按固定顺序写字段，`load` 按同样顺序读回。
//! 建议每个模块以 `w.tag(b"XXXX")` / `r.tag(b"XXXX")?` 开头，错位时能立即定位到模块。

use std::fmt;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum StateError {
    /// 数据提前结束。
    Truncated,
    /// 文件头 magic 不是 `GBEMUST`。
    BadMagic,
    /// 存档版本与当前实现不符。
    BadVersion(u16),
    /// ROM 指纹（头部校验和、全局校验和、标题）与当前卡带不符。
    RomMismatch,
    /// 模块标签不符或字段取值非法；参数说明位置。
    Corrupt(&'static str),
}

impl fmt::Display for StateError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            StateError::Truncated => write!(f, "save state truncated"),
            StateError::BadMagic => write!(f, "not a gbemu save state"),
            StateError::BadVersion(v) => write!(f, "unsupported save state version {v}"),
            StateError::RomMismatch => write!(f, "save state belongs to a different ROM"),
            StateError::Corrupt(what) => write!(f, "corrupt save state: {what}"),
        }
    }
}

impl std::error::Error for StateError {}

pub trait Snapshot {
    fn save(&self, w: &mut StateWriter);
    fn load(&mut self, r: &mut StateReader) -> Result<(), StateError>;
}

#[derive(Debug, Default)]
pub struct StateWriter {
    buf: Vec<u8>,
}

impl StateWriter {
    pub fn new() -> Self {
        Self { buf: Vec::new() }
    }
    pub fn into_inner(self) -> Vec<u8> {
        self.buf
    }
    pub fn len(&self) -> usize {
        self.buf.len()
    }
    pub fn is_empty(&self) -> bool {
        self.buf.is_empty()
    }
    /// 4 字节模块标签，用于检测错位。
    pub fn tag(&mut self, t: &[u8; 4]) {
        self.buf.extend_from_slice(t);
    }
    pub fn u8(&mut self, v: u8) {
        self.buf.push(v);
    }
    pub fn bool(&mut self, v: bool) {
        self.buf.push(v as u8);
    }
    pub fn u16(&mut self, v: u16) {
        self.buf.extend_from_slice(&v.to_le_bytes());
    }
    pub fn u32(&mut self, v: u32) {
        self.buf.extend_from_slice(&v.to_le_bytes());
    }
    pub fn u64(&mut self, v: u64) {
        self.buf.extend_from_slice(&v.to_le_bytes());
    }
    pub fn i64(&mut self, v: i64) {
        self.buf.extend_from_slice(&v.to_le_bytes());
    }
    /// 定长字节（读回时用 `StateReader::bytes_into`，长度由调用方保证一致）。
    pub fn bytes(&mut self, v: &[u8]) {
        self.buf.extend_from_slice(v);
    }
    /// 变长字节：u32 长度前缀 + 数据（读回时用 `StateReader::vec`）。
    pub fn vec(&mut self, v: &[u8]) {
        self.u32(v.len() as u32);
        self.buf.extend_from_slice(v);
    }
}

#[derive(Debug)]
pub struct StateReader<'a> {
    data: &'a [u8],
    pos: usize,
}

impl<'a> StateReader<'a> {
    pub fn new(data: &'a [u8]) -> Self {
        Self { data, pos: 0 }
    }
    pub fn remaining(&self) -> usize {
        self.data.len() - self.pos
    }
    fn take(&mut self, n: usize) -> Result<&'a [u8], StateError> {
        if self.remaining() < n {
            return Err(StateError::Truncated);
        }
        let s = &self.data[self.pos..self.pos + n];
        self.pos += n;
        Ok(s)
    }
    pub fn tag(&mut self, t: &[u8; 4]) -> Result<(), StateError> {
        if self.take(4)? == t {
            Ok(())
        } else {
            Err(StateError::Corrupt("module tag mismatch"))
        }
    }
    pub fn u8(&mut self) -> Result<u8, StateError> {
        Ok(self.take(1)?[0])
    }
    pub fn bool(&mut self) -> Result<bool, StateError> {
        match self.u8()? {
            0 => Ok(false),
            1 => Ok(true),
            _ => Err(StateError::Corrupt("bool")),
        }
    }
    pub fn u16(&mut self) -> Result<u16, StateError> {
        Ok(u16::from_le_bytes(self.take(2)?.try_into().unwrap()))
    }
    pub fn u32(&mut self) -> Result<u32, StateError> {
        Ok(u32::from_le_bytes(self.take(4)?.try_into().unwrap()))
    }
    pub fn u64(&mut self) -> Result<u64, StateError> {
        Ok(u64::from_le_bytes(self.take(8)?.try_into().unwrap()))
    }
    pub fn i64(&mut self) -> Result<i64, StateError> {
        Ok(i64::from_le_bytes(self.take(8)?.try_into().unwrap()))
    }
    pub fn bytes_into(&mut self, out: &mut [u8]) -> Result<(), StateError> {
        out.copy_from_slice(self.take(out.len())?);
        Ok(())
    }
    pub fn vec(&mut self) -> Result<Vec<u8>, StateError> {
        let n = self.u32()? as usize;
        Ok(self.take(n)?.to_vec())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn roundtrip_all_types() {
        let mut w = StateWriter::new();
        w.tag(b"TEST");
        w.u8(0xAB);
        w.bool(true);
        w.u16(0x1234);
        w.u32(0xDEADBEEF);
        w.u64(0x0123_4567_89AB_CDEF);
        w.i64(-5);
        w.bytes(&[1, 2, 3]);
        w.vec(&[9, 8]);
        let data = w.into_inner();
        let mut r = StateReader::new(&data);
        r.tag(b"TEST").unwrap();
        assert_eq!(r.u8().unwrap(), 0xAB);
        assert!(r.bool().unwrap());
        assert_eq!(r.u16().unwrap(), 0x1234);
        assert_eq!(r.u32().unwrap(), 0xDEADBEEF);
        assert_eq!(r.u64().unwrap(), 0x0123_4567_89AB_CDEF);
        assert_eq!(r.i64().unwrap(), -5);
        let mut three = [0u8; 3];
        r.bytes_into(&mut three).unwrap();
        assert_eq!(three, [1, 2, 3]);
        assert_eq!(r.vec().unwrap(), vec![9, 8]);
        assert_eq!(r.remaining(), 0);
        assert_eq!(r.u8(), Err(StateError::Truncated));
    }

    #[test]
    fn tag_mismatch_is_error() {
        let mut w = StateWriter::new();
        w.tag(b"AAAA");
        let data = w.into_inner();
        assert!(StateReader::new(&data).tag(b"BBBB").is_err());
    }
}
