        let v = Value::Obj(vec![
            ("a".into(), Value::Bool(true)),
            ("b".into(), Value::Num(3584.0)),
            ("c".into(), Value::Str("x \"y\"\n\u{1}, 03-op sp,hl.gb".into())),
