    fn write_ram(&mut self, addr: u16, v: u8);
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum CartError {
    /// ROM 小于 0x150 字节（放不下头部）或不是 16 KiB 的整数倍。
    BadSize(usize),
    /// 不支持的卡带类型（头部 0x147）。
    UnsupportedType(u8),
}

