//! bank 号按 ROM 实际 bank 数取模；RAM 最多 4×8 KiB，按实际大小取模。多卡带（MBC1M）未实现。

use super::{load_ram, Cart, RAM_BANK, ROM_BANK};
use crate::state::{Snapshot, StateError, StateReader, StateWriter};

const KIND_MBC1: u8 = 1;

pub struct Mbc1 {
    rom: Vec<u8>,
    rom_banks: usize,
    ram: Vec<u8>,
    ram_enabled: bool,
    /// 5 位 ROM bank 寄存器（原值，未做 0→1 转换）。
    bank1: u8,
    /// 2 位高位寄存器。
    bank2: u8,
    /// banking mode（0 或 1）。
    mode: u8,
    // 由寄存器推出的偏移，寄存器变化时重算。
    rom0_off: usize,
    romx_off: usize,
    ram_off: usize,
}

impl Mbc1 {
    /// `rom` 的长度必须是 `rom_banks` 个 16 KiB。
    pub fn new(rom: Vec<u8>, rom_banks: usize, ram_len: usize) -> Self {
        debug_assert_eq!(rom.len(), rom_banks * ROM_BANK);
        let mut m = Self {
            rom,
            rom_banks,
            ram: vec![0; ram_len],
            ram_enabled: false,
            bank1: 0,
            bank2: 0,
            mode: 0,
            rom0_off: 0,
            romx_off: 0,
            ram_off: 0,
        };
        m.remap();
        m
    }

    fn remap(&mut self) {
        let low = if self.bank1 == 0 { 1 } else { self.bank1 as usize };
        let high = (self.bank2 as usize) << 5;
        let zero = if self.mode == 1 { high } else { 0 };
        self.rom0_off = (zero % self.rom_banks) * ROM_BANK;
