fn malformed_baseline_is_an_error_not_an_empty_baseline() {
    let cur = gates_json(&[("G1", A, false)]);
    for bad in [r#"{}"#, r#"{"results":{}}"#, r#"{"results":[{"rom":"x"}]}"#, r#"{"results":[{"pass":true}]}"#] {
