#[test]
fn fibonacci_passes() {
    assert_eq!(judge_mooneye(&RunEnd::Finished, Some(MOONEYE_PASS_REGS)), Verdict::Pass);
    assert_eq!(MOONEYE_PASS_REGS, [3, 5, 8, 13, 21, 34]);
